await T('Ripples of Potential phase out (threatened)',async()=>{const g=fresh();quiet(g);const [a,b]=g.players;W(g,a,2,'Island');const x=put(g,a,bear());x.counters=1;const kill=tagCard(mk('Murder','Instant','{1}{B}{B}','Destroy target creature.',3));b.hand.push(kill);W(g,b,3,'Swamp');const sp=spell(g,b,kill);sp.target=x;x.owner=0;const r=C('Ripples of Potential');a.hand.push(r);await g.cast(a,r,'hand',null,{instant:true});ok('Ripples of Potential: countered creature under threat can phase out',x.phasedTurn===g.turn||x.protTurn===g.turn,`pt=${x.phasedTurn}`);});

