await T('Rootha, Mastering the Moment',async()=>{const g=fresh();quiet(g);const [a]=g.players;put(g,a,C('Rootha, Mastering the Moment'));await g.fireTriggers(a,'combatStart');await flush(g);ok('Rootha: no instant/sorcery cast -> no token',toks(a).length===0);const cre=cr('Guy','Ogre','{1}{G}',2,2,2);a.hand.push(cre);W(g,a,2,'Forest');await g.cast(a,cre,'hand');await flush(g);await g.fireTriggers(a,'combatStart');await flush(g);ok('Rootha: creature spell does not count',toks(a).length===0);const s1=tagCard(mk('Sorc3','Sorcery','{2}{R}','You gain 1 life.',3));const s2=tagCard(mk('Inst1','Instant','{U}','You gain 1 life.',1));a.hand.push(s1,s2);W(g,a,4,'Mountain');await g.cast(a,s1,'hand');await flush(g);await g.cast(a,s2,'hand',null,{instant:true});await flush(g);await g.fireTriggers(a,'combatStart');await flush(g);const t=toks(a)[0];ok('Rootha: X = greatest MV (3/3 flying haste)',t&&t.card.power===3&&t.card.toughness===3&&t.card.kw.includes('flying')&&!t.summoning,t?`${t.card.power}/${t.card.toughness} ${t.card.kw}`:'none');});
