// ---- Beledros
// ENGINE BUG (generic activated-ability parse ignores "Activate only once each turn" (no oncePerTurn))
await T('Beledros Witherbloom',async()=>{const g=fresh();const [a]=g.players;const be=put(g,a,C('Beledros Witherbloom'));W(g,a,3,'Forest');a.battlefield.filter(x=>x.card.isLand).forEach(x=>x.tapped=true);const o=g.abilityOptions(a,{}).find(o=>o.card===be.card&&o.ab.cost.life===10||o.card===be.card&&o.ab.life===10);ok('Beledros: option',!!o);const l0=a.life;if(o){await g.activate(a,o);await flush(g);}ok('Beledros: lands untapped, paid 10',a.battlefield.filter(x=>x.card.isLand).every(x=>!x.tapped)&&l0-a.life===10,String(l0-a.life));a.battlefield.filter(x=>x.card.isLand).forEach(x=>x.tapped=true);const o2=g.abilityOptions(a,{}).find(o=>o.card===be.card&&o.ab.life===10);ok('Beledros: only once each turn',!o2);g.turn++;const o3=g.abilityOptions(a,{}).find(o=>o.card===be.card&&o.ab.life===10);ok('Beledros: again next turn',!!o3);});

