await T('Regal Force',async()=>{const g=fresh();quiet(g);const [a,b]=g.players;put(g,a,bear());put(g,a,bear());put(g,a,cr('Red','Goblin','{1}{R}',2,2,2));opp(g,b,bear());W(g,a,7,'Forest');const rf=C('Regal Force');a.hand.push(rf);const h=a.hand.length-1;await g.cast(a,rf,'hand');await flush(g);ok('Regal Force: draw per green creature you control (2 bears + itself = 3)',a.hand.length-h===3,String(a.hand.length-h));});

// ---- Yisan
// ENGINE BUG (Yisan: activated ability not parsed at all -- cost "Put a verse counter on Yisan" fails costParts)
await T('Yisan, the Wanderer Bard',async()=>{const g=fresh();const [a]=g.players;const y=put(g,a,C('Yisan, the Wanderer Bard'));W(g,a,3,'Forest');const c1=cr('One','Elf','{G}',1,1,1),c2=cr('Two','Elf','{1}{G}',2,2,2);a.library=[c2,c1,L('Forest')];const o=g.abilityOptions(a,{}).find(o=>o.card===y.card);ok('Yisan: verse ability available',!!o);if(o){await g.activate(a,o);await flush(g);}ok('Yisan: 1 verse counter -> MV1 creature (not MV2)',a.battlefield.some(x=>x.card===c1)&&!a.battlefield.some(x=>x.card===c2),`bf=${a.battlefield.map(x=>x.card.name)}`);});
// ENGINE BUG (Yisan: card.tutor makes resolving Yisan itself tutor a creature onto the battlefield)
await T('Yisan cast does not tutor',async()=>{const g=fresh();quiet(g);const [a]=g.players;W(g,a,3,'Forest');const y=C('Yisan, the Wanderer Bard');a.hand.push(y);const c4=cr('Four','Elf','{3}{G}',4,4,4);a.library=[L('Forest'),c4,L('Forest')];await g.cast(a,y,'hand');await flush(g);ok('Yisan: casting Yisan does not search for a creature',!a.battlefield.some(x=>x.card===c4)&&!a.hand.includes(c4),`bf=${a.battlefield.map(x=>x.card.name)}`);});

