// ---- Bennie Bracks
// (fireTriggers('eachEnd') skips eCond, so the real end step inside takeTurn is used; draws are counted)
for(const withTok of [false,true])await T('Bennie Bracks, Zoologist '+withTok,async()=>{const g=fresh();const [a]=g.players;put(g,a,C('Bennie Bracks, Zoologist'));if(withTok)put(g,a,tagCard(mk('Maker','Enchantment','{2}','At the beginning of your upkeep, create a 1/1 white Soldier creature token.',2)));a.hand=[];let cnt=0;const od=g.draw.bind(g);g.draw=async(p,n)=>{if(p===a)cnt+=n;return od(p,n)};await g.takeTurn(a);ok('Bennie Bracks: '+(withTok?'token created -> end-step draw (2 draws incl. draw step)':'no token -> no end-step draw (1 draw)'),cnt===(withTok?2:1),String(cnt));});
await T('Bennie Bracks opponent token',async()=>{const g=fresh();const [a,b]=g.players;put(g,a,C('Bennie Bracks, Zoologist'));put(g,b,tagCard(mk('Maker','Enchantment','{2}','At the beginning of your upkeep, create a 1/1 white Soldier creature token.',2)));let cnt=0;const od=g.draw.bind(g);g.draw=async(p,n)=>{if(p===a)cnt+=n;return od(p,n)};g.active=1;await g.takeTurn(b);ok("Bennie Bracks: only opponent created a token -> no draw at that end step",cnt===0,String(cnt));});

