await T('Gamble',async()=>{const g=fresh();quiet(g);const [a]=g.players;W(g,a,1,'Mountain');const gm=C('Gamble');const want=tagCard(mk('Wanted','Sorcery','{3}{R}','Draw three cards.',4));a.hand=[gm,bear(),bear()];a.library=[want,...Array(10).fill(0).map(()=>L('Forest'))];const n=a.library.length;await g.cast(a,gm,'hand');await flush(g);ok('Gamble: searched a card (library -1)',a.library.length===n-1&&!a.library.includes(want));ok('Gamble: then discards a card at random (hand 2 +1 -1 = 2)',a.hand.length===2&&a.graveyard.filter(c=>c!==gm).length===1,`h=${a.hand.length} gy=${a.graveyard.map(c=>c.name)}`);});

